mapper.select:
/*common.coco.getBuyerCategorySearch*/
SELECT A.STD_CATEG_ID, A.CATEG_NAME, A.CATEG_TYPE, DECODE((SELECT COUNT(*) FROM ITEMATTR T WHERE T.STDCATEG_ID = A.STD_CATEG_ID), 0,'N','Y') AS MASTER_CHECK, DECODE(A.CATEG_TYPE,'REG','0', ( SELECT COUNT(DISTINCT X.BUYER_ITEM_NO) FROM ICOMBYIT X WHERE X.BUYER = A.COM_CODE AND X.CATEGORY_NO = A.STD_CATEG_ID AND X.STATUS <> 'D' AND X.PRODUCT_CLOSE_FLAG = 'N') ) AS CNT, A.CATEG_PATH FROM ICOMBYCA A WHERE A.COM_CODE = ( SELECT DISTINCT BYCA_COMORG_CODE FROM ICOMCMPY WHERE (COM_CODE = #{st_buyer} OR BYCA_COMORG_CODE = #{st_buyer}) ) AND A.DEPTH = #{st_depth} AND A.STATUS != 'D' AND A.STD_CATEG_ID IN ( SELECT DISTINCT STD_CATEG_ID FROM ( SELECT STD_CATEG_ID FROM ICOMBYCA A, ICOMCOD3 B WHERE A.COM_CODE=B.BUYER AND A.COM_CODE = ( SELECT DISTINCT BYCA_COMORG_CODE FROM ICOMCMPY WHERE (COM_CODE = #{st_buyer} OR BYCA_COMORG_CODE = #{st_buyer}) ) AND A.COM_CODE = B.TEXT1 AND B.TYPE = 'URCT2' AND B.CODE1 = #{st_user_id} AND B.FLAG = 'Y' AND SUBSTR(A.CATEG_SYS_CODE,1,8) = B.TEXT2 UNION ALL SELECT DISTINCT STD_CATEG_ID FROM ICOMBYCA A WHERE A.COM_CODE = ( SELECT DISTINCT BYCA_COMORG_CODE FROM ICOMCMPY WHERE (COM_CODE = #{st_buyer} OR BYCA_COMORG_CODE = #{st_buyer}) ) AND NOT EXISTS ( SELECT 1 FROM ICOMCOD3 B WHERE B.BUYER = A.COM_CODE AND B.TEXT1 = A.COM_CODE AND B.TEXT2 = SUBSTR(A.CATEG_SYS_CODE,1,8) AND B.TYPE = 'URCT2' AND B.FLAG = 'Y' ) ) )
AND A.PID = #{st_categ_code}
ORDER BY A.CATEG_SYS_CODE
